import {controller, target} from '@github/catalyst'
import {CopilotAnimation, CopilotAnimationType} from '@github-ui/copilot-animation'
import {createReactRootErrorHandlers} from '@github-ui/react-core/react-root-error-handlers'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {createRoot, type Root} from 'react-dom/client'

const DEFAULT_REDIRECT = '/settings/copilot/features'

// TODO(copy): finalize all user-facing strings below with content/design before
// launch. Keep them short and reassuring. The "settling" line is intentionally
// generic/informational because it covers the brief window while the new limit
// propagates — avoid implementation detail like "limit"/"quota".
const COPY = {
  processingTitle: 'Processing your payment',
  processingDetail: 'Charging your payment method…',
  appliedTitle: 'Payment applied',
  // TODO(copy): more generic + informational than "Updating your usage limit".
  settlingDetail: 'Finishing up',
  // Final beat shown just before we send the user back.
  // TODO(copy): wording for the "all done, sending you back" moment.
  allSetTitle: "You're all set",
  returningDetail: 'Taking you back…',
  failureTitle: "Payment didn't go through",
  retry: 'Try again',
  // Shown under a non-retryable decline instead of the retry button.
  // TODO(copy): wording for "this won't succeed on retry, do X instead".
  notRetryableHint: 'Please update your payment method before trying again.',
  // Shown when the payment requires a manual authorization step (e.g. India RBI).
  redirectTitle: 'One extra step needed',
  redirectDetail: 'Taking you to complete payment…',
}

// Tints for the Copilot animation per state (the mark uses currentColor).
const ACCENT = 'var(--fgColor-accent, #0969da)'
const SUCCESS = 'var(--fgColor-success, #1a7f37)'
const DANGER = 'var(--fgColor-danger, #cf222e)'
// Size of the Copilot mark across states (suggested octave sizes: 48/64/72/96).
const ANIM_SIZE = 72
// How long the final "Activate" beat plays before we redirect (matches the
// animation's ~2s running duration).
const ACTIVATE_MS = 2000

// TODO(copy): generic fallback shown when the server doesn't return a reason.
const GENERIC_ERROR = "We couldn't process your payment. Please try again."

interface PayToContinueResponse {
  ok?: boolean
  redirect?: string
  error?: string
  // TODO(decline): the server should set this from the orchestrator's decline reason
  // so we can tell the user whether retrying is worthwhile. Most hard declines
  // (e.g. fraud, do-not-honor) will fail again on retry, so when this is false we
  // hide the retry button and point them at updating their payment method instead.
  // Defaults to retryable (true) until the backend populates it.
  retryable?: boolean
}

// Drives an inline Copilot checkout (pay-to-continue and CFI upgrade): intercepts the
// form submit, posts it via fetch, and morphs the order-summary card through a
// Copilot-animated processing -> applied flow (a brief, calm delay that lets billing
// settle), then redirects to the server-provided destination. Payment failures are
// shown inline with a retry, without leaving the page.
@controller('copilot-checkout-progress')
export class CopilotCheckoutProgressElement extends HTMLElement {
  @target declare form: HTMLFormElement
  @target declare checkout: HTMLElement
  @target declare result: HTMLElement
  @target declare errorMessage: HTMLElement

  #redirecting = false
  #animationRoot: Root | undefined
  #timers: number[] = []

  // How long to hold the "applied" state before redirecting. Exposed via data-attrs
  // so tests can run with no delay.
  get holdMs(): number {
    const raw = Number(this.getAttribute('data-hold-ms'))
    return Number.isFinite(raw) && raw >= 0 ? raw : 4000
  }

  // Minimum time to keep the "processing" state visible. Overridable (and set to 0
  // in tests) via data-min-processing-ms.
  get minProcessingMs(): number {
    const raw = Number(this.getAttribute('data-min-processing-ms'))
    return Number.isFinite(raw) && raw >= 0 ? raw : 1200
  }

  connectedCallback() {
    this.#injectStyles()
  }

  disconnectedCallback() {
    this.#clearTimers()
    this.#unmountAnimation()
  }

  async submit(event?: Event) {
    event?.preventDefault()
    if (this.#redirecting) return

    this.#hideError()
    this.#renderProcessing()
    const startedAt = Date.now()

    let response: Response
    try {
      response = await verifiedFetch(this.form.action, {
        method: 'POST',
        headers: {Accept: 'application/json'},
        body: new FormData(this.form),
      })
    } catch {
      await this.#minDwell(startedAt)
      this.#renderFailure(GENERIC_ERROR, true)
      return
    }

    let data: PayToContinueResponse = {}
    try {
      data = (await response.json()) as PayToContinueResponse
    } catch {
      // fall through to status check below
    }

    // Keep the processing state up for a minimum beat so the loader is actually
    // visible (and we don't flash) even when the charge returns quickly.
    await this.#minDwell(startedAt)

    if (response.ok && data.ok) {
      this.#renderApplied()
      this.#redirecting = true
      const redirect = data.redirect || DEFAULT_REDIRECT
      // Success holds while the limit settles, then the Activate beat plays as we get
      // close to the redirect.
      const activateAt = Math.max(0, this.holdMs - ACTIVATE_MS)
      this.#timers.push(window.setTimeout(() => this.#renderActivating(), activateAt))
      this.#timers.push(window.setTimeout(() => this.navigate(redirect), this.holdMs))
    } else if (!data.ok && data.redirect) {
      // The payment requires an extra step (e.g. India RBI manual authorization).
      // Show an informational state and navigate to the redirect URL.
      const redirectUrl = data.redirect
      this.#renderRedirectRequired(data.error || COPY.redirectDetail)
      this.#redirecting = true
      this.#timers.push(window.setTimeout(() => this.navigate(redirectUrl), this.holdMs))
    } else {
      // retryable defaults to true until the backend populates it (see interface TODO).
      this.#renderFailure(data.error || GENERIC_ERROR, data.retryable !== false)
    }
  }

  async #minDwell(startedAt: number) {
    const remaining = this.minProcessingMs - (Date.now() - startedAt)
    if (remaining > 0) await new Promise(resolve => setTimeout(resolve, remaining))
  }

  // Navigates to the post-payment destination. Overridable in tests so we don't have
  // to stub the non-configurable window.location.assign.
  navigate(url: string) {
    window.location.assign(url)
  }

  retry(event?: Event) {
    event?.preventDefault()
    this.#hideError()
    this.#showCheckout()
  }

  #renderProcessing() {
    const wrap = this.#node('div', {class: 'cptc-state', role: 'status', 'aria-live': 'polite'})
    const animHost = this.#node('div', {class: 'cptc-anim', 'aria-hidden': 'true'})
    wrap.append(
      animHost,
      this.#node('p', {class: 'cptc-title'}, COPY.processingTitle),
      this.#node('p', {class: 'cptc-shimmer'}, COPY.processingDetail),
    )
    this.#showResult(wrap)
    // Thinking while we wait on the charge.
    this.#mountCopilotAnimation(animHost, CopilotAnimationType.Thinking, {loop: true, color: ACCENT})
  }

  #renderApplied() {
    const wrap = this.#node('div', {class: 'cptc-state', role: 'status', 'aria-live': 'polite'})
    const animHost = this.#node('div', {class: 'cptc-anim', 'aria-hidden': 'true'})

    // Settling line: generic copy + the little loading dots while the new limit
    // propagates before we redirect.
    const sub = this.#node('p', {class: 'cptc-muted cptc-settling'}, COPY.settlingDetail)
    const dots = this.#node('span', {class: 'cptc-dots'})
    dots.append(this.#node('span', {}, '.'), this.#node('span', {}, '.'), this.#node('span', {}, '.'))
    sub.append(dots)

    wrap.append(animHost, this.#node('p', {class: 'cptc-title'}, COPY.appliedTitle), sub)
    this.#showResult(wrap)
    // Celebratory jump on success, tinted green.
    this.#mountCopilotAnimation(animHost, CopilotAnimationType.JumpWiggle, {color: SUCCESS})
  }

  #renderActivating() {
    const wrap = this.#node('div', {class: 'cptc-state', role: 'status', 'aria-live': 'polite'})
    const animHost = this.#node('div', {class: 'cptc-anim', 'aria-hidden': 'true'})
    wrap.append(
      animHost,
      this.#node('p', {class: 'cptc-title'}, COPY.allSetTitle),
      this.#node('p', {class: 'cptc-muted'}, COPY.returningDetail),
    )
    this.#showResult(wrap)
    // Activate flourish as we hand the user back, kept green to stay on the success note.
    this.#mountCopilotAnimation(animHost, CopilotAnimationType.Activate, {color: SUCCESS})
  }

  // Shown when the payment can't complete inline and the user must authorize it
  // elsewhere (e.g. India RBI manual payment). Informational, not a failure — the
  // Thinking animation signals "in progress" and we navigate after a brief hold.
  #renderRedirectRequired(message: string) {
    const wrap = this.#node('div', {class: 'cptc-state', role: 'status', 'aria-live': 'polite'})
    const animHost = this.#node('div', {class: 'cptc-anim', 'aria-hidden': 'true'})
    wrap.append(
      animHost,
      this.#node('p', {class: 'cptc-title'}, COPY.redirectTitle),
      this.#node('p', {class: 'cptc-muted'}, message),
    )
    this.#showResult(wrap)
    this.#mountCopilotAnimation(animHost, CopilotAnimationType.Thinking, {loop: true, color: ACCENT})
  }

  #renderFailure(message: string, retryable: boolean) {
    const wrap = this.#node('div', {class: 'cptc-state', role: 'alert'})
    const animHost = this.#node('div', {class: 'cptc-anim', 'aria-hidden': 'true'})
    wrap.append(
      animHost,
      this.#node('p', {class: 'cptc-title'}, COPY.failureTitle),
      this.#node('p', {class: 'cptc-muted'}, message),
    )

    // Only offer a retry when the decline is plausibly retryable. Hard declines
    // (fraud, do-not-honor, etc.) won't succeed on retry, so we steer the user to
    // fixing their payment method instead. TODO(decline): drive this off a real
    // decline code once the backend sets `retryable` on the JSON response.
    if (retryable) {
      wrap.append(
        this.#node(
          'button',
          {type: 'button', class: 'btn btn-primary cptc-retry', 'data-action': 'click:copilot-checkout-progress#retry'},
          COPY.retry,
        ),
      )
    } else {
      wrap.append(this.#node('p', {class: 'cptc-muted cptc-retry'}, COPY.notRetryableHint))
    }

    this.#showResult(wrap)
    // Negative gesture, tinted red.
    this.#mountCopilotAnimation(animHost, CopilotAnimationType.Negative, {color: DANGER})
  }

  #showResult(node: Node) {
    this.#unmountAnimation()
    if (this.checkout) this.checkout.hidden = true
    if (this.result) {
      this.result.replaceChildren(node)
      this.result.hidden = false
    }
  }

  #showCheckout() {
    this.#clearTimers()
    this.#unmountAnimation()
    if (this.result) {
      this.result.replaceChildren()
      this.result.hidden = true
    }
    if (this.checkout) this.checkout.hidden = false
  }

  // Mounts the shared @github-ui/copilot-animation React component into `host`, tinted
  // per state via `color` (the mark uses currentColor).
  #mountCopilotAnimation(host: HTMLElement, type: CopilotAnimationType, opts: {loop?: boolean; color?: string} = {}) {
    const {loop = false, color} = opts
    const errorHandlers = createReactRootErrorHandlers({appName: 'copilot-checkout-progress'})
    this.#animationRoot = createRoot(host, errorHandlers)
    this.#animationRoot.render(
      <CopilotAnimation
        animationType={type}
        loopAnimation={loop}
        size={ANIM_SIZE}
        style={color ? {color} : undefined}
      />,
    )
  }

  #unmountAnimation() {
    if (!this.#animationRoot) return
    const root = this.#animationRoot
    this.#animationRoot = undefined
    // Defer to avoid React's "unmount during render" warning if called mid-cycle.
    queueMicrotask(() => root.unmount())
  }

  #clearTimers() {
    for (const id of this.#timers) window.clearTimeout(id)
    this.#timers = []
  }

  #hideError() {
    if (!this.errorMessage) return
    this.errorMessage.textContent = ''
    this.errorMessage.removeAttribute('role')
    this.errorMessage.hidden = true
  }

  // Builds an element with attributes and optional text content (textContent escapes
  // any dynamic strings, so this is XSS-safe without innerHTML).
  #node(tag: string, attrs: Record<string, string> = {}, text?: string): HTMLElement {
    const node = document.createElement(tag)
    for (const [name, value] of Object.entries(attrs)) node.setAttribute(name, value)
    if (text != null) node.textContent = text
    return node
  }

  #injectStyles() {
    if (document.getElementById('cptc-styles')) return
    const style = document.createElement('style')
    style.id = 'cptc-styles'
    style.textContent = `
      .cptc-state { text-align: center; padding: var(--base-size-12) var(--base-size-4); }
      .cptc-title { font-size: 16px; font-weight: 600; margin: var(--base-size-12) 0 var(--base-size-4); }
      .cptc-muted { color: var(--fgColor-muted, #59636e); margin: 0; }
      .cptc-anim { display: flex; align-items: center; justify-content: center; min-height: 80px;
        color: var(--fgColor-accent, #0969da); }
      .cptc-shimmer { margin: 0; color: var(--fgColor-muted, #59636e);
        -webkit-mask-image: linear-gradient(90deg, rgba(0,0,0,.35) 0%, rgba(0,0,0,1) 50%, rgba(0,0,0,.35) 100%);
        mask-image: linear-gradient(90deg, rgba(0,0,0,.35) 0%, rgba(0,0,0,1) 50%, rgba(0,0,0,.35) 100%);
        -webkit-mask-size: 200% 100%; mask-size: 200% 100%; animation: cptc-shimmer 1.3s infinite linear; }
      .cptc-settling { display: inline-flex; align-items: center; justify-content: center; gap: 2px; }
      .cptc-dots span { opacity: .2; }
      .cptc-dots span:nth-child(1) { animation: cptc-dot 1.2s infinite; }
      .cptc-dots span:nth-child(2) { animation: cptc-dot 1.2s infinite .2s; }
      .cptc-dots span:nth-child(3) { animation: cptc-dot 1.2s infinite .4s; }
      .cptc-retry { margin-top: var(--base-size-16); }
      @keyframes cptc-shimmer { 0% { -webkit-mask-position: 100% 0; mask-position: 100% 0; } 100% { -webkit-mask-position: -100% 0; mask-position: -100% 0; } }
      @keyframes cptc-dot { 0%,60%,100% { opacity: .2; } 30% { opacity: 1; } }
      @media (prefers-reduced-motion: reduce) {
        .cptc-shimmer, .cptc-dots span { animation: none !important; }
      }
    `
    document.head.appendChild(style)
  }
}
